","import React from "react";

interface EBProps {
 children: React.ReactNode;
}

interface EBState {
 hasError: boolean;
 errorMsg: string;
}

export default class ErrorBoundary extends React.Component<EBProps, EBState> {
 state: EBState = { hasError: false, errorMsg: "" };

 static getDerivedStateFromError(error: Error): EBState {
 return { hasError: true, errorMsg: error?.message || "Unknown error" };
 }

 componentDidCatch(error: Error, info: React.ErrorInfo) {
 console.error("Portal Error:", error, info.componentStack);
 }

 render(): React.ReactNode {
 if (this.state.hasError) {
 return (
 <div style={{
 padding: "2rem",
 maxWidth: "600px",
 margin: "4rem auto",
 fontFamily: "Lato, Arial, sans-serif",
 textAlign: "center" as const
 }}>
 <h2 style={{ marginBottom: "1rem", color: "#101719" }}>
 Something went wrong
 </h2>
 <p style={{ color: "#4b5559", marginBottom: "1rem" }}>
 The portal encountered an error. Please refresh the page or contact your administrator.
 </p>
 <pre style={{
 background: "#f5f6f7",
 padding: "1rem",
 borderRadius: "6px",
 fontSize: "0.75rem",
 textAlign: "left" as const,
 overflow: "auto",
 color: "#e52239"
 }}>
 {this.state.errorMsg}
 </pre>
 </div>
 );
 }
 return (this as any).props.children;
 }
}
","/* ================================================================
 VoltWorks Visitor Portal — Horizon Design System Theming
 ================================================================ */

/* === Alias Layer === */
:root {
 --snx-color-surface: rgb(var(--now-color_background--primary, 255, 255, 255));
 --snx-color-surface-alt: rgb(var(--now-color_background--secondary, 245, 246, 247));
 --snx-color-surface-dark: rgb(var(--now-color_background--tertiary, 226, 229, 231));
 --snx-color-border: rgb(var(--now-container--border-color, 207, 213, 215));
 --snx-color-text: rgb(var(--now-color_text--primary, 16, 23, 26));
 --snx-color-text-muted: rgb(var(--now-color_text--secondary, 75, 85, 89));
 --snx-color-primary: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
 --snx-color-on-primary: rgb(var(--now-actionable_label--primary--color, 255, 255, 255));
 --snx-color-positive: rgb(var(--now-indicator--primary_positive--background-color, 53, 147, 37));
 --snx-color-focus: rgb(var(--now-color_focus-ring, 53, 147, 37));
 --snx-radius-container: var(--now-container--border-radius, 8px);
 --snx-radius-card: var(--now-container-card--border-radius, 8px);
 --snx-font-body: var(--now-font-family, "Lato", Arial, sans-serif);
}

/* === Global Reset === */
*, *::before, *::after {
 box-sizing: border-box;
}

body {
 margin: 0;
 padding: 0;
 font-family: var(--snx-font-body);
 color: var(--snx-color-text);
 background-color: var(--snx-color-surface-alt);
 line-height: var(--now-static-line-height, 1.25);
}

h1, h2, h3, p {
 margin: 0;
}

/* === Portal Shell === */
.portal {
 display: flex;
 flex-direction: column;
 min-height: 100vh;
}

.portal__content {
 flex: 1;
 max-width: 1200px;
 width: 100%;
 margin: 0 auto;
 padding: var(--now-static-space--xl, 1.5rem);
}

/* === Portal Header === */
.portal-header {
 display: flex;
 justify-content: space-between;
 align-items: center;
 padding: var(--now-static-space--md, 0.75rem) var(--now-static-space--xl, 1.5rem);
 background-color: var(--snx-color-surface);
 border-bottom: 1px solid var(--snx-color-border);
 box-shadow: var(--now-static-drop-shadow--sm);
 position: sticky;
 top: 0;
 z-index: 100;
}

.portal-header__brand {
 display: flex;
 align-items: center;
 gap: var(--now-static-space--sm, 0.5rem);
}

.portal-header__logo {
 display: flex;
 align-items: center;
 justify-content: center;
 width: 2.5rem;
 height: 2.5rem;
 border-radius: var(--snx-radius-container);
 background-color: var(--snx-color-primary);
 color: var(--snx-color-on-primary);
}

.portal-header__icon {
 width: 1.25rem;
 height: 1.25rem;
}

.portal-header__titles {
 display: flex;
 flex-direction: column;
}

.portal-header__title {
 font-size: var(--now-static-font-size--lg, 1.25rem);
 font-weight: 700;
 color: var(--snx-color-text);
}

.portal-header__subtitle {
 font-size: var(--now-static-font-size--sm, 0.75rem);
 color: var(--snx-color-text-muted);
}

.portal-header__nav {
 display: flex;
 gap: var(--now-static-space--sm, 0.5rem);
}

/* === Home View === */
.home__hero {
 text-align: center;
 padding: var(--now-static-space--3xl, 2.5rem) var(--now-static-space--xl, 1.5rem);
 background-color: var(--snx-color-surface);
 border-radius: var(--snx-radius-card);
 border: 1px solid var(--snx-color-border);
 margin-bottom: var(--now-static-space--xl, 1.5rem);
}

.home__hero-title {
 font-size: 1.75rem;
 font-weight: 700;
 color: var(--snx-color-text);
 margin-bottom: var(--now-static-space--sm, 0.5rem);
}

.home__hero-subtitle {
 font-size: 1rem;
 color: var(--snx-color-text-muted);
 max-width: 600px;
 margin: 0 auto;
 line-height: 1.5;
}

/* === Action Cards === */
.home__cards {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
 gap: var(--now-static-space--xl, 1.5rem);
 margin-bottom: var(--now-static-space--xl, 1.5rem);
}

.action-card {
 background-color: var(--snx-color-surface);
 border: 1px solid var(--snx-color-border);
 border-radius: var(--snx-radius-card);
 padding: var(--now-static-space--xl, 1.5rem);
 display: flex;
 flex-direction: column;
 gap: var(--now-static-space--md, 0.75rem);
 transition: box-shadow 150ms ease, border-color 150ms ease;
}

.action-card:hover {
 box-shadow: var(--now-static-drop-shadow--md);
 border-color: var(--snx-color-primary);
}

.action-card__icon-wrap {
 display: flex;
 align-items: center;
 justify-content: center;
 width: 3rem;
 height: 3rem;
 border-radius: var(--snx-radius-container);
}

.action-card__icon-wrap--create {
 background-color: rgba(var(--now-actionable--primary--background-color, 0, 128, 163), 0.1);
 color: var(--snx-color-primary);
}

.action-card__icon-wrap--track {
 background-color: rgba(var(--now-indicator--primary_positive--background-color, 53, 147, 37), 0.1);
 color: var(--snx-color-positive);
}

.action-card__icon {
 width: 1.5rem;
 height: 1.5rem;
}

.action-card__title {
 font-size: var(--now-static-font-size--lg, 1.25rem);
 font-weight: 600;
 color: var(--snx-color-text);
}

.action-card__desc {
 font-size: 0.875rem;
 color: var(--snx-color-text-muted);
 line-height: 1.5;
 flex: 1;
}

.action-card__action {
 padding-top: var(--now-static-space--sm, 0.5rem);
}

/* === What to Expect Steps === */
.home__info {
 background-color: var(--snx-color-surface);
 border: 1px solid var(--snx-color-border);
 border-radius: var(--snx-radius-card);
 padding: var(--now-static-space--xl, 1.5rem);
}

.home__info-title {
 font-size: var(--now-static-font-size--lg, 1.25rem);
 font-weight: 600;
 color: var(--snx-color-text);
 margin-bottom: var(--now-static-space--lg, 1rem);
}

.home__steps {
 display: flex;
 flex-direction: column;
 gap: var(--now-static-space--md, 0.75rem);
}

.step-item {
 display: flex;
 align-items: flex-start;
 gap: var(--now-static-space--md, 0.75rem);
}

.step-item__number {
 display: flex;
 align-items: center;
 justify-content: center;
 min-width: 2rem;
 height: 2rem;
 border-radius: 50%;
 background-color: var(--snx-color-primary);
 color: var(--snx-color-on-primary);
 font-weight: 700;
 font-size: 0.875rem;
}

.step-item__text {
 color: var(--snx-color-text-muted);
 font-size: 0.875rem;
 line-height: 1.6;
 padding-top: 0.25rem;
}

.step-item__text strong {
 color: var(--snx-color-text);
}

/* === Request List === */
.request-list__header {
 display: flex;
 justify-content: space-between;
 align-items: center;
 margin-bottom: var(--now-static-space--lg, 1rem);
}

.request-list__title {
 font-size: 1.5rem;
 font-weight: 700;
 color: var(--snx-color-text);
}

.request-list__table {
 background-color: var(--snx-color-surface);
 border: 1px solid var(--snx-color-border);
 border-radius: var(--snx-radius-card);
 overflow: hidden;
}

/* === Create Request === */
.create-request__header {
 margin-bottom: var(--now-static-space--xl, 1.5rem);
}

.create-request__title {
 font-size: 1.5rem;
 font-weight: 700;
 color: var(--snx-color-text);
 margin-top: var(--now-static-space--sm, 0.5rem);
}

.create-request__subtitle {
 font-size: 0.875rem;
 color: var(--snx-color-text-muted);
 margin-top: var(--now-static-space--xs, 0.25rem);
 line-height: 1.5;
}

.create-request__form {
 background-color: var(--snx-color-surface);
 border: 1px solid var(--snx-color-border);
 border-radius: var(--snx-radius-card);
 padding: var(--now-static-space--xl, 1.5rem);
}

/* === Request Detail === */
.request-detail__header {
 margin-bottom: var(--now-static-space--xl, 1.5rem);
}

.request-detail__title {
 font-size: 1.5rem;
 font-weight: 700;
 color: var(--snx-color-text);
 margin-top: var(--now-static-space--sm, 0.5rem);
}

.request-detail__form {
 background-color: var(--snx-color-surface);
 border: 1px solid var(--snx-color-border);
 border-radius: var(--snx-radius-card);
 padding: var(--now-static-space--xl, 1.5rem);
}

/* === Navigation Buttons === */
.nav-btn {
 display: inline-flex;
 align-items: center;
 justify-content: center;
 padding: 0.375rem 1rem;
 border-radius: var(--now-actionable--border-radius, 6px);
 font-size: 0.875rem;
 font-weight: 600;
 font-family: inherit;
 text-decoration: none;
 cursor: pointer;
 border: 1px solid var(--snx-color-border);
 background-color: var(--snx-color-surface);
 color: var(--snx-color-text);
 transition: background-color 100ms ease, border-color 100ms ease;
}

.nav-btn:hover {
 background-color: var(--snx-color-surface-alt);
 border-color: var(--snx-color-text-muted);
}

.nav-btn--primary {
 background-color: var(--snx-color-primary);
 color: var(--snx-color-on-primary);
 border-color: var(--snx-color-primary);
}

.nav-btn--primary:hover {
 opacity: 0.9;
 background-color: var(--snx-color-primary);
 border-color: var(--snx-color-primary);
}

.nav-btn--active {
 border-color: var(--snx-color-primary);
 color: var(--snx-color-primary);
}

.nav-btn--back {
 border: none;
 background: none;
 padding: 0.25rem 0;
 color: var(--snx-color-primary);
}

.nav-btn--back:hover {
 background: none;
 border: none;
 text-decoration: underline;
}

/* === Loading Spinner === */
.portal-loading {
 display: flex;
 flex-direction: column;
 align-items: center;
 justify-content: center;
 padding: 4rem 2rem;
}

.portal-loading__spinner {
 width: 2.5rem;
 height: 2.5rem;
 border: 3px solid var(--snx-color-border);
 border-top-color: var(--snx-color-primary);
 border-radius: 50%;
 animation: spin 0.8s linear infinite;
 margin-bottom: var(--now-static-space--md, 0.75rem);
}

@keyframes spin {
 to { transform: rotate(360deg); }
}

.portal-loading__text {
 color: var(--snx-color-text-muted);
 font-size: 0.875rem;
}

/* === Action Card Clickable === */
.action-card {
 cursor: pointer;
}

.action-card:focus-visible {
 outline: 2px solid var(--snx-color-focus);
 outline-offset: 2px;
}

/* === Form Elements === */
.form-card {
 background-color: var(--snx-color-surface);
 border: 1px solid var(--snx-color-border);
 border-radius: var(--snx-radius-card);
 padding: var(--now-static-space--xl, 1.5rem);
 margin: 0;
}

.form-grid {
 display: grid;
 grid-template-columns: 1fr 1fr;
 gap: var(--now-static-space--lg, 1rem);
}

.form-field { display: flex; flex-direction: column; }
.form-field--full { grid-column: 1 / -1; }

.form-label {
 font-weight: 600;
 font-size: 0.8125rem;
 color: var(--snx-color-text);
 margin-bottom: var(--now-static-space--xs, 0.25rem);
}

.form-input, .form-select, .form-textarea {
 padding: 0.5rem 0.75rem;
 border: 1px solid var(--snx-color-border);
 border-radius: var(--now-form-control-input--primary--border-radius, 4px);
 background-color: var(--snx-color-surface);
 color: var(--snx-color-text);
 font-family: inherit;
 font-size: 0.875rem;
 line-height: 1.5;
}

.form-input:focus, .form-select:focus, .form-textarea:focus {
 outline: none;
 border-color: var(--snx-color-primary);
 box-shadow: 0 0 0 2px rgba(var(--now-color_focus-ring, 53, 147, 37), 0.25);
}

.form-textarea { resize: vertical; }
.form-select { cursor: pointer; }

.form-checkbox {
 display: flex;
 align-items: center;
 gap: 0.5rem;
 font-size: 0.875rem;
 color: var(--snx-color-text-muted);
 cursor: pointer;
 padding-top: 0.25rem;
}

.form-actions {
 display: flex;
 justify-content: flex-end;
 gap: var(--now-static-space--sm, 0.5rem);
 margin-top: var(--now-static-space--xl, 1.5rem);
 padding-top: var(--now-static-space--lg, 1rem);
 border-top: 1px solid var(--snx-color-border);
}

.form-error {
 background-color: rgba(var(--now-indicator--primary_critical--background-color, 229, 34, 57), 0.08);
 color: rgb(var(--now-indicator--primary_critical--background-color, 229, 34, 57));
 border: 1px solid rgba(var(--now-indicator--primary_critical--background-color, 229, 34, 57), 0.3);
 border-radius: var(--snx-radius-card);
 padding: 0.75rem 1rem;
 margin-bottom: var(--now-static-space--lg, 1rem);
 font-size: 0.875rem;
}

.form-success {
 text-align: center;
 padding: 4rem 2rem;
}

.form-success__icon {
 display: inline-flex;
 align-items: center;
 justify-content: center;
 width: 4rem;
 height: 4rem;
 border-radius: 50%;
 background-color: var(--snx-color-positive);
 color: white;
 font-size: 2rem;
 margin-bottom: var(--now-static-space--lg, 1rem);
}

/* === Host Lookup === */
.host-lookup { position: relative; }

.host-lookup__selected {
 display: block;
 font-size: 0.75rem;
 color: var(--snx-color-positive);
 margin-bottom: 0.25rem;
}

.host-lookup__dropdown {
 position: absolute;
 top: 100%;
 left: 0;
 right: 0;
 background-color: var(--snx-color-surface);
 border: 1px solid var(--snx-color-border);
 border-radius: 0 0 4px 4px;
 box-shadow: var(--now-static-drop-shadow--md);
 z-index: 50;
 max-height: 200px;
 overflow-y: auto;
}

.host-lookup__item {
 display: flex;
 flex-direction: column;
 padding: 0.5rem 0.75rem;
 cursor: pointer;
}

.host-lookup__item:hover {
 background-color: var(--snx-color-surface-alt);
}

.host-lookup__name { font-size: 0.875rem; color: var(--snx-color-text); }
.host-lookup__email { font-size: 0.75rem; color: var(--snx-color-text-muted); }

/* === List View === */
.list-header, .list-row {
 display: grid;
 grid-template-columns: 1fr 1.2fr 1.2fr 1.5fr 1.2fr;
 padding: 0.75rem 1rem;
 align-items: center;
 font-size: 0.875rem;
}

.list-header {
 background-color: var(--snx-color-surface-alt);
 font-weight: 600;
 color: var(--snx-color-text);
 border-bottom: 1px solid var(--snx-color-border);
}

.list-row {
 border-bottom: 1px solid var(--snx-color-border);
 cursor: pointer;
 color: var(--snx-color-text-muted);
 transition: background-color 100ms ease;
}

.list-row:hover { background-color: var(--snx-color-surface-alt); }
.list-row:last-child { border-bottom: none; }
.list-row__number { color: var(--snx-color-primary); font-weight: 600; }

/* === Status Badges === */
.badge {
 display: inline-block;
 padding: 0.125rem 0.5rem;
 border-radius: 10px;
 font-size: 0.75rem;
 font-weight: 600;
}

.badge--info { background-color: rgba(var(--now-actionable--primary--background-color, 0, 128, 163), 0.12); color: var(--snx-color-primary); }
.badge--positive { background-color: rgba(var(--now-indicator--primary_positive--background-color, 53, 147, 37), 0.12); color: var(--snx-color-positive); }
.badge--warning { background-color: rgba(var(--now-indicator--primary_warning--background-color, 224, 148, 24), 0.12); color: rgb(var(--now-indicator--primary_warning--background-color, 224, 148, 24)); }
.badge--critical { background-color: rgba(var(--now-indicator--primary_critical--background-color, 229, 34, 57), 0.12); color: rgb(var(--now-indicator--primary_critical--background-color, 229, 34, 57)); }
.badge--muted { background-color: var(--snx-color-surface-alt); color: var(--snx-color-text-muted); }

/* === Detail View === */
.detail-card {
 background-color: var(--snx-color-surface);
 border: 1px solid var(--snx-color-border);
 border-radius: var(--snx-radius-card);
 overflow: hidden;
}

.detail-row {
 display: grid;
 grid-template-columns: 200px 1fr;
 border-bottom: 1px solid var(--snx-color-border);
}

.detail-row:last-child { border-bottom: none; }

.detail-row__label {
 padding: 0.75rem 1rem;
 font-weight: 600;
 font-size: 0.8125rem;
 color: var(--snx-color-text);
 background-color: var(--snx-color-surface-alt);
}

.detail-row__value {
 padding: 0.75rem 1rem;
 font-size: 0.875rem;
 color: var(--snx-color-text-muted);
}

/* === Empty State === */
.empty-state {
 text-align: center;
 padding: 4rem 2rem;
 background-color: var(--snx-color-surface);
 border: 1px solid var(--snx-color-border);
 border-radius: var(--snx-radius-card);
}

.empty-state p {
 color: var(--snx-color-text-muted);
 margin-bottom: var(--now-static-space--lg, 1rem);
}

/* === Responsive === */
@media (max-width: 768px) {
 .portal-header {
 flex-direction: column;
 gap: var(--now-static-space--sm, 0.5rem);
 }

 .portal-header__nav {
 width: 100%;
 justify-content: center;
 }

 .home__cards {
 grid-template-columns: 1fr;
 }

 .portal__content {
 padding: var(--now-static-space--md, 0.75rem);
 }
}
","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
}","import React, { useState, useEffect, useCallback, Suspense, lazy } from "react";
import "./app.css";

const PortalHeader = lazy(() => import("./components/PortalHeader"));
const HomeView = lazy(() => import("./components/HomeView"));
const RequestList = lazy(() => import("./components/RequestList"));
const CreateRequest = lazy(() => import("./components/CreateRequest"));
const RequestDetail = lazy(() => import("./components/RequestDetail"));

interface ViewState {
 view: string;
 recordId: string | null;
}

function getViewFromUrl(): ViewState {
 const params = new URLSearchParams(window.location.search);
 return {
 view: params.get("view") || "home",
 recordId: params.get("id") || null,
 };
}

function LoadingSpinner() {
 return (
 <div className="portal-loading">
 <div className="portal-loading__spinner" />
 <p className="portal-loading__text">Loading portal...</p>
 </div>
 );
}

export default function App() {
 const [currentView, setCurrentView] = useState<ViewState>(getViewFromUrl);

 useEffect(() => {
 const onPopState = () => setCurrentView(getViewFromUrl());
 window.addEventListener("popstate", onPopState);
 return () => window.removeEventListener("popstate", onPopState);
 }, []);

 const navigateToView = useCallback(
 (viewName: string, recordId?: string | null, options?: { title?: string }) => {
 const params = new URLSearchParams({ view: viewName });
 if (recordId) params.set("id", recordId);
 const relativePath = `${window.location.pathname}?${params}`;
 const pageTitle = options?.title || `VoltWorks Portal - ${viewName.charAt(0).toUpperCase() + viewName.slice(1)}`;

 if (window.self !== window.top) {
 (window as any).CustomEvent.fireTop("magellanNavigator.permalink.set", {
 relativePath,
 title: pageTitle,
 });
 }

 window.history.pushState({ viewName, recordId }, "", relativePath);
 document.title = pageTitle;
 setCurrentView({ view: viewName, recordId: recordId || null });
 },
 []
 );

 const { view, recordId } = currentView;

 return (
 <div className="portal">
 <Suspense fallback={<LoadingSpinner />}>
 <PortalHeader currentView={view} navigateToView={navigateToView} />
 </Suspense>
 <main className="portal__content">
 <Suspense fallback={<LoadingSpinner />}>
 {view === "home" && <HomeView navigateToView={navigateToView} />}
 {view === "requests" && <RequestList navigateToView={navigateToView} />}
 {view === "create" && <CreateRequest navigateToView={navigateToView} />}
 {view === "detail" && recordId && (
 <RequestDetail recordId={recordId} navigateToView={navigateToView} />
 )}
 </Suspense>
 </main>
 </div>
 );
}
","import React from "react";
